const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '支点' },
      { kind: 'text', payload: '动力臂' },
      { kind: 'text', payload: '阻力臂' },
      { kind: 'text', payload: '动力臂与阻力臂长度比 = 4 : 1' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var DW = 480;
    var DH = 340;
    var s = Math.min(W / DW, H / DH);
    if (!(s > 0)) { s = 1; }
    var ox = (W - DW * s) / 2;
    var oy = (H - DH * s) / 2;

    function X(x) { return ox + x * s; }
    function Y(y) { return oy + y * s; }
    function P(p) { return [X(p[0]), Y(p[1])]; }
    function seg(a, b) { return visualSdk.polyline([P(a), P(b)]); }
    function sw(v) { var r = v * s; return r < 1 ? 1 : r; }

    function textSize(i, fallback, fs) {
      var m = metrics && metrics[i];
      var w = 0;
      var h = 0;
      if (m) {
        if (typeof m.width === 'number') { w = m.width; }
        else if (typeof m.w === 'number') { w = m.w; }
        else if (m.bbox && typeof m.bbox.width === 'number') { w = m.bbox.width; }
        if (typeof m.height === 'number') { h = m.height; }
        else if (typeof m.h === 'number') { h = m.h; }
        else if (m.bbox && typeof m.bbox.height === 'number') { h = m.bbox.height; }
      }
      if (!(w > 0)) { w = fallback.length * fs; }
      if (!(h > 0)) { h = fs * 1.3; }
      return { w: w, h: h };
    }

    var FS = 16;
    var FS2 = 13;
    var t1 = textSize(1, '动力臂', FS);
    var t2 = textSize(2, '阻力臂', FS);

    var Lp = [140, 230];
    var Fp = [200, 222];
    var Rp = [440, 190];

    var bdx = Rp[0] - Lp[0];
    var bdy = Rp[1] - Lp[1];
    var blen = Math.sqrt(bdx * bdx + bdy * bdy);
    var nx = -bdy / blen;
    var ny = bdx / blen;

    var off = 30;
    var Lo = [Lp[0] - nx * off, Lp[1] - ny * off];
    var Fo = [Fp[0] - nx * off, Fp[1] - ny * off];
    var Ro = [Rp[0] - nx * off, Rp[1] - ny * off];
    var tk = 5.5;

    var paths = [];
    var children = [];

    function addPath(id, cmds, attrs) {
      paths.push({ id: id, commands: cmds });
      var node = { type: 'path', pathId: id };
      if (attrs) {
        for (var k in attrs) {
          if (Object.prototype.hasOwnProperty.call(attrs, k)) { node[k] = attrs[k]; }
        }
      }
      children.push(node);
    }

    addPath('ground', seg([18, 270], [462, 270]), { stroke: '#5b6b7c', strokeWidth: sw(2.5) });

    addPath('bar', seg(Lp, Rp), { stroke: '#a06a33', strokeWidth: sw(9), strokeLinecap: 'round' });

    var rockPts = [[55, 270], [47, 244], [58, 222], [84, 210], [114, 210], [146, 222], [154, 248], [150, 270]];
    var rockCmd = visualSdk.polyline(rockPts.map(P)).concat(['Z']);
    addPath('rock', rockCmd, { fill: '#b7c0ca', stroke: '#4c5a68', strokeWidth: sw(2) });

    var fulcrumPts = [[182, 270], [200, 222], [218, 270]];
    var fulcrumCmd = visualSdk.polyline(fulcrumPts.map(P)).concat(['Z']);
    addPath('fulcrum', fulcrumCmd, { fill: '#7d8b99', stroke: '#3d4a57', strokeWidth: sw(1.8) });

    for (var k = 1; k <= 3; k++) {
      var dx = Fp[0] + 60 * k;
      var dy = Fp[1] - 8 * k;
      addPath('div' + k, seg([dx - nx * 7, dy - ny * 7], [dx + nx * 7, dy + ny * 7]), { stroke: '#f3e6d3', strokeWidth: sw(1.6) });
    }

    addPath('dimRes', seg(Lo, Fo), { stroke: '#2f6fb3', strokeWidth: sw(1.4) });
    addPath('dimResA', seg([Lo[0] - nx * tk, Lo[1] - ny * tk], [Lo[0] + nx * tk, Lo[1] + ny * tk]), { stroke: '#2f6fb3', strokeWidth: sw(1.4) });
    addPath('dimResB', seg([Fo[0] - nx * tk, Fo[1] - ny * tk], [Fo[0] + nx * tk, Fo[1] + ny * tk]), { stroke: '#2f6fb3', strokeWidth: sw(1.4) });

    addPath('dimEff', seg(Fo, Ro), { stroke: '#2f6fb3', strokeWidth: sw(1.4) });
    addPath('dimEffB', seg([Ro[0] - nx * tk, Ro[1] - ny * tk], [Ro[0] + nx * tk, Ro[1] + ny * tk]), { stroke: '#2f6fb3', strokeWidth: sw(1.4) });

    addPath('lead', seg([200, 272], [200, 286]), { stroke: '#1f2c3d', strokeWidth: sw(1.2) });

    addPath('force', visualSdk.arrow(X(440), Y(138), X(440), Y(184), {}), { stroke: '#2f6fb3', strokeWidth: sw(2.2) });

    var gap1 = Math.min(Math.max(t1.h, 10), 30) * 0.6;
    var gap2 = Math.min(Math.max(t2.h, 10), 30) * 0.6;

    children.push({ type: 'label', text: '动力臂', x: X((Fo[0] + Ro[0]) / 2), y: Y((Fo[1] + Ro[1]) / 2 - gap1), fontSize: FS * s, fill: '#1f3a5f', textAnchor: 'middle' });
    children.push({ type: 'label', text: '阻力臂', x: X((Lo[0] + Fo[0]) / 2 - 4), y: Y((Lo[1] + Fo[1]) / 2 - gap2), fontSize: FS * s, fill: '#1f3a5f', textAnchor: 'middle' });
    children.push({ type: 'label', text: '支点', x: X(200), y: Y(302), fontSize: FS * s, fill: '#1f2c3d', textAnchor: 'middle' });
    children.push({ type: 'label', text: '动力臂与阻力臂长度比 = 4 : 1', x: X(28), y: Y(324), fontSize: FS2 * s, fill: '#4a5a6b', textAnchor: 'start' });

    return {
      schemaVersion: 1,
      sceneId: 'lever-rock',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
